import{_ as r,l as o,o as t,c as n,v as e,p as s,x as l,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"宪法式 RL 实践","description":"","frontmatter":{"title":"宪法式 RL 实践","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/constitutional-rl-practice.md","filePath":"llm/constitutional-rl-practice.md","lastUpdated":1789023840000}'),E={name:"llm/constitutional-rl-practice.md"};function h(A,a,m,u,_,f){const i=o("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="宪法式-rl-实践" tabindex="-1">宪法式 RL 实践 <a class="header-anchor" href="#宪法式-rl-实践" aria-label="Permalink to &quot;宪法式 RL 实践&quot;">​</a></h1><div class="epigraph"><p>原则写进比较提示，无害通道就可以少让人读有害文本；原则仍是人写的，冲突仍要产品拍板。</p><footer>—— Bai 等 Constitutional AI；实践中的 RLAIF、书面规范与分类器叠层</footer></div><p><a href="/llm/scalable-oversight">上一课</a>把宪法列为放大人类规范的一种协议。主干课 <a href="/llm/constitutional-ai">Constitutional AI</a> 已写 SL-CAI 与 RL-CAI。本课写<strong>实践缺口</strong>：原则清单如何维护、如何与 <a href="/llm/rlhf-pipeline">RLHF</a> 的人类有用通道共存、如何避免把宪法当不可审计的提示魔法。接到拒绝训练与诚实课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAI 原文：有用仍可人类比较；无害用原则驱动的模型批评、改写、再比较。落地后出现三件事。一，原则冲突（「要有帮助」vs「拒绝犯罪」）在清单内部，模型会挑对它容易的条款。二，RL 阶段的偏好模型过优化原则的字面（免责声明变长）。三，后来的分类器层（constitutional classifiers）与生成策略不是同一对象，实践上常常两层都要，原文只改策略。</p><p>实践问题是版本化：哪一版宪法训了哪一版策略，红队用哪一版，事故归因才能做。</p><h3 id="宪法不是形式验证" tabindex="-1">宪法不是形式验证 <a class="header-anchor" href="#宪法不是形式验证" aria-label="Permalink to &quot;宪法不是形式验证&quot;">​</a></h3><p>条款是自然语言，没有把输出空间切成安全语言。随机抽若干条做批评，只是降低单条捷径。与细则奖励课相同：合同必须贯穿标注、训练、评测。这里的合同是原则文本。</p><p><span class="marginnote">减少的是无害性人类比较，不是全部人类。红队题、原则撰写、有用比较仍是人。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护：原则 git 化，每条附反例与预期行为。训练：SL 批评-改写 → 模型比较造对 → RM + PPO 或 DPO，无害 \\(r\\) 仅来自原则比较；有用 \\(r\\) 来自人。合成用 <a href="/llm/multi-objective-reward">多目标加权</a> 的硬门：原则失败则封顶。推理：可再跑分类器，不把训练过的策略当成唯一闸。评测：原则覆盖的伤害类型 + 过拒绝（XSTest 一类）必须成对报。</p>',11)),(t(),s(d,null,{default:l(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONS%5B%22%E7%89%88%E6%9C%AC%E5%8C%96%E5%8E%9F%E5%88%99%22%5D%20--%3E%20SL%5B%22%E6%89%B9%E8%AF%84-%E6%94%B9%E5%86%99%20SFT%22%5D%0A%20%20CONS%20--%3E%20CMP%5B%22%E6%A8%A1%E5%9E%8B%E6%8C%89%E5%8E%9F%E5%88%99%E6%AF%94%E8%BE%83%22%5D%0A%20%20CMP%20--%3E%20RM%5B%22%E6%97%A0%E5%AE%B3%20RM%22%5D%0A%20%20HUM%5B%22%E4%BA%BA%E7%B1%BB%E6%9C%89%E7%94%A8%E6%AF%94%E8%BE%83%22%5D%20--%3E%20RM2%5B%22%E6%9C%89%E7%94%A8%20RM%22%5D%0A%20%20RM%20--%3E%20MIX%5B%22%E7%A1%AC%E9%97%A8%20%2B%20%E5%8A%A0%E6%9D%83%22%5D%0A%20%20RM2%20--%3E%20MIX%0A%20%20MIX%20--%3E%20PPO%5B%22PPO%20%2F%20DPO%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>与自奖励的差别：比较器提示冻结为宪法，不让正在优化的 \\(\\pi\\) 随意改原则。原则更新是发布事件，不是训练步。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>原则把无害规范从标注员脑子里挪到可公开检查的文本，这是治理收益。RL 仍会 Goodhart 文本表面。实践对策：原则外红队、过拒绝金标、不把监视原则写进过强奖励（monitorability）。CAI 与校验器互补：能程序判定的伤害（明显恶意代码执行）走沙箱；规范判断走宪法。</p><p><span class="marginnote">多语言原则不是翻译一遍了事。同一条款在不同语言的模型比较里校准会漂。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>开源复现常缺红队预算，只剩「加一段系统原则」当 CAI，那是提示，不是 RL 实践。下一课拒绝训练把「何时不答」写成可优化行为，宪法是其规范来源之一，过拒绝是主要副作用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实践中的宪法式 RL：原则版本化、无害 AI 比较、有用人类比较、硬门合成。</li><li>原则会被字面过优化；需红队与过拒绝金标。</li><li>分类器层与策略层是两道闸，不是互相替代。</li><li>比较器冻结，不让当前 π 改宪法。</li><li>出处：Bai 等 CAI；RLAIF 实践；Llama 2 分头作对照；过拒绝评测见后课。</li></ul>',8))])}const P=r(E,[["render",h]]);export{C as __pageData,P as default};
